//! Heading identity, anchors and slugs (spec section 3.1; G33 in docs/TEST_PLAN.md).
//!
//! `heading_plain_text` strips inline Markdown the way a CommonMark renderer would (backslash
//! escapes, code spans, entities, links, images, emphasis, raw HTML, autolinks; plus GFM
//! `~~strike~~` and MDQ `==mark==`), then applies NFC and collapses white space. The Unicode
//! and entity tables are generated by scripts/gen_unicode_tables.py.

use crate::diag::{Code, Diagnostic};
use crate::entities::ENTITIES;
use crate::unitab::{CASEFOLD, KEEP, PUNCT, ZS};
use crate::vars::{html_inline_end, tag_end};
use std::cmp::Ordering;
use std::collections::{HashMap, HashSet};
use unicode_normalization::UnicodeNormalization;

type Res<T> = Result<T, Diagnostic>;

const MAX_INPUT: usize = 16 * 1024 * 1024;

fn in_ranges(tab: &[(u32, u32)], cp: u32) -> bool {
    tab.binary_search_by(|&(a, b)| {
        if cp < a {
            Ordering::Greater
        } else if cp > b {
            Ordering::Less
        } else {
            Ordering::Equal
        }
    })
    .is_ok()
}

pub(crate) fn u_ws(c: char) -> bool {
    matches!(c, ' ' | '\t' | '\n' | '\u{c}' | '\r') || in_ranges(ZS, c as u32)
}

fn u_punct(c: char) -> bool {
    c.is_ascii_punctuation() || (c as u32 > 127 && in_ranges(PUNCT, c as u32))
}

pub(crate) fn entity_at(c: &[char], i: usize, n: usize) -> Option<(String, usize)> {
    let mut j = i + 1;
    if j < n && c[j] == '#' {
        j += 1;
        let hexa = j < n && (c[j] == 'x' || c[j] == 'X');
        if hexa {
            j += 1;
        }
        let s = j;
        let max = if hexa { 6 } else { 7 };
        while j < n && (if hexa { c[j].is_ascii_hexdigit() } else { c[j].is_ascii_digit() }) && j - s < max {
            j += 1;
        }
        if j == s || j >= n || c[j] != ';' {
            return None;
        }
        let digits: String = c[s..j].iter().collect();
        let cp = u32::from_str_radix(&digits, if hexa { 16 } else { 10 }).ok()?;
        let ch = if cp == 0 { '\u{fffd}' } else { char::from_u32(cp).unwrap_or('\u{fffd}') };
        return Some((ch.to_string(), j + 1));
    }
    let s = j;
    if !(j < n && c[j].is_ascii_alphabetic()) {
        return None;
    }
    while j < n && c[j].is_ascii_alphanumeric() && j - s < 32 {
        j += 1;
    }
    if j >= n || c[j] != ';' || j - s < 2 {
        return None;
    }
    let name: String = c[s..j].iter().collect();
    let idx = ENTITIES.binary_search_by_key(&name.as_str(), |e| e.0).ok()?;
    Some((ENTITIES[idx].1.to_string(), j + 1))
}

fn skip_ws_link(c: &[char], i: usize, n: usize) -> usize {
    let mut i = i;
    while i < n && (c[i] == ' ' || c[i] == '\t') {
        i += 1;
    }
    if i < n && (c[i] == '\n' || c[i] == '\r') {
        i += if c[i] == '\r' && i + 1 < n && c[i + 1] == '\n' { 2 } else { 1 };
        while i < n && (c[i] == ' ' || c[i] == '\t') {
            i += 1;
        }
    }
    i
}

fn has_blank_line(t: &[char]) -> bool {
    let m = t.len();
    let mut i = 0;
    while i < m {
        if t[i] == '\n' || t[i] == '\r' {
            i += if t[i] == '\r' && i + 1 < m && t[i + 1] == '\n' { 2 } else { 1 };
            while i < m && (t[i] == ' ' || t[i] == '\t') {
                i += 1;
            }
            if i < m && (t[i] == '\n' || t[i] == '\r') {
                return true;
            }
        } else {
            i += 1;
        }
    }
    false
}

/// An inline link tail `(dest "title")`: `dest` is the destination's char range (inside any
/// `<>`), `end` is exclusive.
pub(crate) struct LinkParts {
    pub dest: (usize, usize),
    pub angle: bool,
    pub end: usize,
}

fn link_tail(c: &[char], i: usize, n: usize) -> Option<usize> {
    link_parts(c, i, n).map(|p| p.end)
}

/// Parse an inline link tail starting at `c[i] == '('`.
pub(crate) fn link_parts(c: &[char], i: usize, n: usize) -> Option<LinkParts> {
    if i >= n || c[i] != '(' {
        return None;
    }
    let mut i = skip_ws_link(c, i + 1, n);
    let mut dest = (0usize, 0usize);
    let mut angle = false;
    if i < n && c[i] == '<' {
        let mut j = i + 1;
        while j < n && c[j] != '\n' && c[j] != '\r' && c[j] != '<' && c[j] != '>' {
            j += if c[j] == '\\' && j + 1 < n && c[j + 1].is_ascii_punctuation() { 2 } else { 1 };
        }
        if j < n && c[j] == '>' {
            dest = (i + 1, j);
            angle = true;
            i = j + 1;
        } else {
            return None;
        }
    } else {
        let mut depth = 0usize;
        let mut j = i;
        while j < n {
            let ch = c[j];
            if ch == '\\' && j + 1 < n && c[j + 1].is_ascii_punctuation() {
                j += 2;
                continue;
            }
            if ch == '(' {
                depth += 1;
                if depth > 32 {
                    return None;
                }
            } else if ch == ')' {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            } else if u_ws(ch) || (ch as u32) < 0x20 || ch as u32 == 0x7f {
                break;
            }
            j += 1;
        }
        if depth != 0 {
            return None;
        }
        dest = (i, j);
        i = j;
    }
    let k = skip_ws_link(c, i, n);
    if k > i && k < n && (c[k] == '"' || c[k] == '\'' || c[k] == '(') {
        let q = c[k];
        let closer = if q == '(' { ')' } else { q };
        let mut j = k + 1;
        while j < n {
            let ch = c[j];
            if ch == '\\' && j + 1 < n && c[j + 1].is_ascii_punctuation() {
                j += 2;
                continue;
            }
            if ch == closer {
                break;
            }
            if q == '(' && ch == '(' {
                return None;
            }
            j += 1;
        }
        if j >= n {
            return None;
        }
        if has_blank_line(&c[k + 1..j]) {
            return None;
        }
        i = skip_ws_link(c, j + 1, n);
    } else {
        i = k;
    }
    if i < n && c[i] == ')' {
        Some(LinkParts { dest, angle, end: i + 1 })
    } else {
        None
    }
}

enum Seg {
    T(String),
    D(usize),
    B(usize),
}

struct Delim {
    ch: char,
    orig: usize,
    count: usize,
    can_open: bool,
    can_close: bool,
    alive: bool,
}

struct Brk {
    image: bool,
    active: bool,
    kept: bool,
    top: usize,
}

fn next_alive(delims: &[Delim], k: usize) -> Option<usize> {
    let mut k = k;
    while k < delims.len() && !delims[k].alive {
        k += 1;
    }
    if k < delims.len() {
        Some(k)
    } else {
        None
    }
}

fn process(delims: &mut [Delim], bottom: usize) {
    let mut excl: HashMap<(char, bool, usize), isize> = HashMap::new();
    let mut k = next_alive(delims, bottom);
    while let Some(ki) = k {
        if !delims[ki].can_close {
            k = next_alive(delims, ki + 1);
            continue;
        }
        let dch = delims[ki].ch;
        let dopen = delims[ki].can_open;
        let dorig = delims[ki].orig;
        let key = (dch, dopen, dorig % 3);
        let lo = *excl.get(&key).unwrap_or(&(bottom as isize - 1));
        let mut found: Option<usize> = None;
        let mut j = ki as isize - 1;
        while j > lo && j >= bottom as isize {
            let o = &delims[j as usize];
            if o.alive && o.ch == dch && o.can_open {
                let odd = (dch == '*' || dch == '_')
                    && (dopen || o.can_close)
                    && dorig % 3 != 0
                    && (o.orig + dorig) % 3 == 0;
                if !odd {
                    found = Some(j as usize);
                    break;
                }
            }
            j -= 1;
        }
        match found {
            Some(fi) => {
                let used = if dch == '~' || dch == '=' {
                    2
                } else if delims[ki].count >= 2 && delims[fi].count >= 2 {
                    2
                } else {
                    1
                };
                delims[fi].count -= used;
                delims[ki].count -= used;
                for m in fi + 1..ki {
                    delims[m].alive = false;
                }
                if delims[fi].count == 0 {
                    delims[fi].alive = false;
                }
                if delims[ki].count == 0 {
                    delims[ki].alive = false;
                    k = next_alive(delims, ki + 1);
                }
            }
            None => {
                excl.insert(key, ki as isize - 1);
                if !delims[ki].can_open {
                    delims[ki].alive = false;
                }
                k = next_alive(delims, ki + 1);
            }
        }
    }
}

fn flush(buf: &mut String, segs: &mut Vec<Seg>) {
    if !buf.is_empty() {
        segs.push(Seg::T(std::mem::take(buf)));
    }
}

/// The text a CommonMark renderer shows for inline Markdown `s` (before NFC and white space
/// normalisation).
fn strip_inline(s: &str) -> String {
    let c: Vec<char> = s.chars().collect();
    let n = c.len();
    let mut segs: Vec<Seg> = Vec::new();
    let mut delims: Vec<Delim> = Vec::new();
    let mut brks: Vec<Brk> = Vec::new();
    let mut bstack: Vec<usize> = Vec::new();
    let mut buf = String::new();
    let mut i = 0;
    while i < n {
        let ch = c[i];
        if ch == '\\' {
            if i + 1 < n && c[i + 1].is_ascii_punctuation() {
                buf.push(c[i + 1]);
                i += 2;
            } else if i + 1 < n && (c[i + 1] == '\n' || c[i + 1] == '\r') {
                buf.push('\n');
                i += if c[i + 1] == '\r' && i + 2 < n && c[i + 2] == '\n' { 3 } else { 2 };
            } else {
                buf.push('\\');
                i += 1;
            }
        } else if ch == '`' {
            let mut j = i;
            while j < n && c[j] == '`' {
                j += 1;
            }
            let run = j - i;
            let mut k = j;
            let mut end: Option<usize> = None;
            while k < n {
                if c[k] == '`' {
                    let mut m = k;
                    while m < n && c[m] == '`' {
                        m += 1;
                    }
                    if m - k == run {
                        end = Some(k);
                        break;
                    }
                    k = m;
                } else {
                    k += 1;
                }
            }
            match end {
                None => {
                    for x in &c[i..j] {
                        buf.push(*x);
                    }
                    i = j;
                }
                Some(e) => {
                    let mut body: Vec<char> = Vec::new();
                    let mut m = j;
                    while m < e {
                        if c[m] == '\r' && m + 1 < e && c[m + 1] == '\n' {
                            body.push(' ');
                            m += 2;
                        } else if c[m] == '\r' || c[m] == '\n' {
                            body.push(' ');
                            m += 1;
                        } else {
                            body.push(c[m]);
                            m += 1;
                        }
                    }
                    let len = body.len();
                    if len >= 2 && body[0] == ' ' && body[len - 1] == ' ' && body.iter().any(|&x| x != ' ') {
                        body = body[1..len - 1].to_vec();
                    }
                    buf.extend(body.iter());
                    i = e + run;
                }
            }
        } else if ch == '<' {
            match html_inline_end(&c, i, n) {
                None => {
                    buf.push('<');
                    i += 1;
                }
                Some(m) => {
                    if i + 1 < n && c[i + 1] != '!' && c[i + 1] != '?' && tag_end(&c, i, n).is_none() {
                        buf.extend(c[i + 1..m - 1].iter());
                    }
                    i = m;
                }
            }
        } else if ch == '&' {
            match entity_at(&c, i, n) {
                None => {
                    buf.push('&');
                    i += 1;
                }
                Some((t, e)) => {
                    buf.push_str(&t);
                    i = e;
                }
            }
        } else if ch == '*' || ch == '_' || ch == '~' || ch == '=' {
            let mut j = i;
            while j < n && c[j] == ch {
                j += 1;
            }
            let run = j - i;
            if (ch == '~' || ch == '=') && run != 2 {
                buf.extend(c[i..j].iter());
                i = j;
                continue;
            }
            let prev = if i > 0 { c[i - 1] } else { ' ' };
            let nx = if j < n { c[j] } else { ' ' };
            let (pw, nw, pp, np) = (u_ws(prev), u_ws(nx), u_punct(prev), u_punct(nx));
            let left = !nw && (!np || pw || pp);
            let right = !pw && (!pp || nw || np);
            let (co, cc) = if ch == '_' {
                (left && (!right || pp), right && (!left || np))
            } else {
                (left, right)
            };
            flush(&mut buf, &mut segs);
            delims.push(Delim { ch, orig: run, count: run, can_open: co, can_close: cc, alive: true });
            segs.push(Seg::D(delims.len() - 1));
            i = j;
        } else if ch == '[' || (ch == '!' && i + 1 < n && c[i + 1] == '[') {
            flush(&mut buf, &mut segs);
            let img = ch == '!';
            brks.push(Brk { image: img, active: true, kept: true, top: delims.len() });
            segs.push(Seg::B(brks.len() - 1));
            bstack.push(brks.len() - 1);
            i += if img { 2 } else { 1 };
        } else if ch == ']' {
            let b = match bstack.last() {
                Some(&b) => b,
                None => {
                    buf.push(']');
                    i += 1;
                    continue;
                }
            };
            if !brks[b].active {
                bstack.pop();
                buf.push(']');
                i += 1;
                continue;
            }
            let end = match link_tail(&c, i + 1, n) {
                Some(e) => e,
                None => {
                    bstack.pop();
                    buf.push(']');
                    i += 1;
                    continue;
                }
            };
            flush(&mut buf, &mut segs);
            let top = brks[b].top;
            process(&mut delims, top);
            for m in top..delims.len() {
                delims[m].alive = false;
            }
            brks[b].kept = false;
            if !brks[b].image {
                for &ob in &bstack {
                    if !brks[ob].image {
                        brks[ob].active = false;
                    }
                }
            }
            bstack.pop();
            i = end;
        } else {
            buf.push(ch);
            i += 1;
        }
    }
    flush(&mut buf, &mut segs);
    process(&mut delims, 0);
    let mut out = String::new();
    for seg in &segs {
        match seg {
            Seg::T(t) => out.push_str(t),
            Seg::D(d) => {
                for _ in 0..delims[*d].count {
                    out.push(delims[*d].ch);
                }
            }
            Seg::B(b) => {
                if brks[*b].kept {
                    out.push_str(if brks[*b].image { "![" } else { "[" });
                }
            }
        }
    }
    out
}

pub(crate) fn collapse_ws(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut pend = false;
    for ch in s.chars() {
        if u_ws(ch) {
            pend = true;
        } else {
            if pend && !out.is_empty() {
                out.push(' ');
            }
            pend = false;
            out.push(ch);
        }
    }
    out
}

pub(crate) fn atx_strip(s: &str) -> String {
    let blank = |c: char| c == ' ' || c == '\t';
    let t = s.trim_end_matches(blank);
    let body = t.trim_end_matches('#');
    if body.len() < t.len() && (body.is_empty() || body.ends_with(blank)) {
        body.trim_end_matches(blank).to_string()
    } else {
        t.to_string()
    }
}

/// Rendered plain text of a heading's inline Markdown. `atx` removes a closing `###` first.
pub fn heading_plain_text(inline: &str, atx: bool) -> Res<String> {
    if inline.len() > MAX_INPUT {
        return Err(Diagnostic::new(Code::ResourceLimit, "input is larger than 16 MiB"));
    }
    let src = if atx { atx_strip(inline) } else { inline.to_string() };
    let text: String = strip_inline(&src).nfc().collect();
    Ok(collapse_ws(&text))
}

/// Index of the first heading whose plain text equals `target` (NFC, white space collapsed).
pub fn heading_match(headings: &[String], target: &str, atx: bool) -> Res<Option<usize>> {
    let key = collapse_ws(&target.nfc().collect::<String>());
    for (k, h) in headings.iter().enumerate() {
        if heading_plain_text(h, atx)? == key {
            return Ok(Some(k));
        }
    }
    Ok(None)
}

/// Portable anchor slug of heading text (spec 3.1).
pub fn slugify(text: &str) -> String {
    let mut out = String::new();
    let mut pend = false;
    let nfc: String = text.nfc().collect();
    let mut emit = |f: char, out: &mut String, pend: &mut bool| {
        if f == '-' || f == '_' || in_ranges(KEEP, f as u32) {
            if *pend && !out.is_empty() {
                out.push('-');
            }
            *pend = false;
            out.push(f);
        } else {
            *pend = true;
        }
    };
    for ch in nfc.chars() {
        match CASEFOLD.binary_search_by_key(&(ch as u32), |e| e.0) {
            Ok(idx) => {
                for f in CASEFOLD[idx].1.chars() {
                    emit(f, &mut out, &mut pend);
                }
            }
            Err(_) => emit(ch, &mut out, &mut pend),
        }
    }
    let trimmed = out.trim_matches('-');
    if trimmed.is_empty() {
        "section".to_string()
    } else {
        trimmed.to_string()
    }
}

/// Deterministic unique anchors: later duplicates get `-2`, `-3`, ...; `reserved` anchors
/// (user block IDs) keep their name and are never reused.
pub fn slug_dedupe(slugs: &[String], reserved: &[String]) -> Vec<String> {
    let mut used: HashSet<String> = reserved.iter().cloned().collect();
    let mut out = Vec::with_capacity(slugs.len());
    for base in slugs {
        let mut cand = base.clone();
        let mut k = 1usize;
        while used.contains(&cand) {
            k += 1;
            cand = format!("{}-{}", base, k);
        }
        used.insert(cand.clone());
        out.push(cand);
    }
    out
}

/// Percent-encode everything except ASCII letters, digits and `-._~`.
pub fn percent_encode_anchor(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for ch in text.chars() {
        if ch.is_ascii_alphanumeric() || matches!(ch, '-' | '.' | '_' | '~') {
            out.push(ch);
        } else {
            let mut b = [0u8; 4];
            for byte in ch.encode_utf8(&mut b).bytes() {
                out.push_str(&format!("%{:02X}", byte));
            }
        }
    }
    out
}
